import { DrillCue, DrillOutcome, WristService } from '@golf/types';
import { FULL_BAND_MIN_TOP_DEG } from '@golf/wrist';
import { Asset } from 'expo-asset';
import {
  AudioPlayer,
  AudioStatus,
  createAudioPlayer,
  setAudioModeAsync,
} from 'expo-audio';
import * as Haptics from 'expo-haptics';

/**
 * Sound + haptic feedback for the wedge drill — the ONLY file that touches
 * expo-audio/expo-haptics (native modules stay at the app edge, same rule as
 * practice-keepalive). The WAVs are generated by tools/generate-drill-audio.mjs.
 * Feedback must never crash the drill: every playback failure is swallowed
 * with a console.warn.
 *
 * Loading is the fragile part, not playing: in a dev-client build a
 * require()'d WAV resolves to a Metro HTTP URL that the NATIVE player fetches
 * at load time — and expo-audio surfaces a failed load only as an `error`
 * field on the playbackStatusUpdate event while the player parks itself in an
 * idle state it never leaves. Unhandled, that is permanent silence with zero
 * JS exceptions, triggered exactly when it hurts: first playback mid-drill on
 * a range where the phone sits on the EYE MINI's network, not the dev LAN.
 * So: preloadFeedback() pins the assets into the local cache up front (call
 * it the moment the drill screen mounts), and every player carries an error
 * listener that re-prepares it instead of letting it die.
 */

type SoundName = 'tick' | 'accent' | 'match' | 'over' | 'under' | 'blip';

// Metro asset ids — resolved at bundle time; Asset.loadAsync turns them into
// local file URIs before the native players are built.
const SOURCES: Record<SoundName, number> = {
  tick: require('../../assets/audio/tick.wav'),
  accent: require('../../assets/audio/accent.wav'),
  match: require('../../assets/audio/match.wav'),
  over: require('../../assets/audio/over.wav'),
  under: require('../../assets/audio/under.wav'),
  blip: require('../../assets/audio/blip.wav'),
};

const SOUND_NAMES: SoundName[] = [
  'tick',
  'accent',
  'match',
  'over',
  'under',
  'blip',
];

/** a load error re-prepares the player at most this many times — a WAV that
    keeps failing must not loop error→replace forever */
const MAX_LOAD_RETRIES = 5;

const warn = (err: unknown): void => {
  console.warn('drill feedback failed', err);
};

let players: Record<SoundName, AudioPlayer> | null = null;
let preloadPromise: Promise<void> | null = null;

function buildPlayer(name: SoundName): AudioPlayer {
  const player = createAudioPlayer(SOURCES[name]);
  let retries = 0;
  player.addListener('playbackStatusUpdate', (status: AudioStatus) => {
    // the native side merges a load/playback failure into the status event —
    // the ONLY place it surfaces; the field is absent from the declared type
    const { error } = status as AudioStatus & { error?: string | null };
    if (typeof error === 'string' && error.length > 0) {
      warn(`${name}: ${error}`);
      if (retries < MAX_LOAD_RETRIES) {
        retries += 1;
        // a failed load parks the player in an idle state nothing revisits —
        // re-pointing at the source forces a fresh prepare
        try {
          player.replace(SOURCES[name]);
        } catch (err) {
          warn(err);
        }
      }
    }
  });
  return player;
}

function buildPlayers(): Record<SoundName, AudioPlayer> {
  return {
    tick: buildPlayer('tick'),
    accent: buildPlayer('accent'),
    match: buildPlayer('match'),
    over: buildPlayer('over'),
    under: buildPlayer('under'),
    blip: buildPlayer('blip'),
  };
}

/**
 * Idempotent warm-up: apply the audio mode, download the WAVs into the local
 * asset cache (so range-time playback never needs the Metro server), and
 * build the native players. Call at drill-screen mount; playback works
 * without it, just through the fragile lazy path.
 */
export function preloadFeedback(): Promise<void> {
  if (preloadPromise) return preloadPromise;
  preloadPromise = (async () => {
    // cues must sound with the ring switch on silent; sequenced here so the
    // mode is in force before the first playback
    try {
      await setAudioModeAsync({
        playsInSilentMode: true,
        interruptionMode: 'mixWithOthers',
      });
    } catch (err) {
      warn(err);
    }
    try {
      await Asset.loadAsync(SOUND_NAMES.map((name) => SOURCES[name]));
    } catch (err) {
      warn(err); // players fall back to the raw asset ids below
    }
    if (!players) {
      players = buildPlayers();
      return;
    }
    // players built by the lazy path resolved their sources BEFORE the cache
    // landed (Metro URLs in a dev client) — re-point them at the now-local
    // files so nothing depends on the network again
    for (const name of SOUND_NAMES) {
      try {
        players[name].replace(SOURCES[name]);
      } catch (err) {
        warn(err);
      }
    }
  })();
  return preloadPromise;
}

function ensurePlayers(): Record<SoundName, AudioPlayer> {
  if (!players) {
    void preloadFeedback().catch(warn); // warms mode + cache for later reps
    players = buildPlayers();
  }
  return players;
}

function playSound(name: SoundName): void {
  try {
    const player = ensurePlayers()[name];
    // rewind first so a retrigger restarts the sound instead of no-opping
    void player
      .seekTo(0)
      .catch(warn)
      .then(() => player.play())
      .catch(warn);
  } catch (err) {
    warn(err);
  }
}

const impact = (style: Haptics.ImpactFeedbackStyle): void => {
  void Haptics.impactAsync(style).catch(warn);
};

/** Instant verdict on a drill rep (fires on the wrist swing event, ~1 s
    before the Mini reports carry). */
export function playOutcome(outcome: DrillOutcome): void {
  switch (outcome) {
    case 'match':
      playSound('match');
      void Haptics.notificationAsync(
        Haptics.NotificationFeedbackType.Success,
      ).catch(warn);
      return;
    case 'over':
      playSound('over');
      // two heavy thuds: unmistakably "too much" through a glove
      impact(Haptics.ImpactFeedbackStyle.Heavy);
      setTimeout(() => impact(Haptics.ImpactFeedbackStyle.Heavy), 120);
      return;
    case 'under':
      playSound('under');
      impact(Haptics.ImpactFeedbackStyle.Light);
      return;
    case 'calibrating':
      playSound('blip');
      void Haptics.selectionAsync().catch(warn);
      return;
  }
}

/**
 * On-wrist marker via the HackMotion motor the moment the detector confirms
 * the top — the "you're there" tap Tim asked for; the audio motif sounding at
 * the same instant carries WHICH verdict. Full-band tops only: a smaller
 * stroke can validate through the chip band's impact-shock gate, and the
 * motor must never be running inside a window that gate reads (motor shock
 * on the IMU is uncharacterized). Reaches the wrist ~30–45 ms of BLE ack
 * plus motor spin-up after the reversal confirms — early downswing, while
 * the club is still up.
 */
export function playTopBuzz(swingThetaDeg: number, wrist: WristService): void {
  if (swingThetaDeg < FULL_BAND_MIN_TOP_DEG) return;
  wrist.vibrate(300);
}

/**
 * On-wrist verdict buzz on the VALIDATED rep (the swing event) — the motor
 * stays quiet through the impact window (chip-band shock gate). Patterns are
 * distinct by feel through a glove: match one crisp pulse, over two, under
 * one long. Pulse lengths sit inside the vendor app's observed envelope
 * (0.4–4.2 s ON) — shorter pulses are unproven on the motor. Calibrating
 * reps get nothing — no target, nothing to confirm.
 */
export function playRepBuzz(outcome: DrillOutcome, wrist: WristService): void {
  switch (outcome) {
    case 'match':
      wrist.vibrate(400);
      return;
    case 'over':
      wrist.vibrate(400);
      setTimeout(() => wrist.vibrate(400), 650);
      return;
    case 'under':
      wrist.vibrate(900);
      return;
    case 'calibrating':
      return;
  }
}

let cancelActiveCue: (() => void) | null = null;

/** Plays the rung's swing song: `beats` ticks evenly spaced across
    [0, backswingMs) — tick i at i·backswingMs/beats — then the accent at
    backswingMs + downswingMs, with Light impacts on ticks and Medium on the
    accent. Returns a cancel function; starting a new cue cancels the
    previous one. */
export function playCue(cue: DrillCue): () => void {
  cancelActiveCue?.();
  const timers: ReturnType<typeof setTimeout>[] = [];
  const schedule = (delayMs: number, fire: () => void): void => {
    timers.push(setTimeout(fire, delayMs));
  };
  for (let i = 0; i < cue.beats; i++) {
    schedule((i * cue.backswingMs) / cue.beats, () => {
      playSound('tick');
      impact(Haptics.ImpactFeedbackStyle.Light);
    });
  }
  schedule(cue.backswingMs + cue.downswingMs, () => {
    playSound('accent');
    impact(Haptics.ImpactFeedbackStyle.Medium);
  });
  const cancel = (): void => {
    for (const timer of timers) clearTimeout(timer);
    if (cancelActiveCue === cancel) cancelActiveCue = null;
  };
  cancelActiveCue = cancel;
  return cancel;
}

/** Stop whatever cue is mid-song (screen exit — ticks must not outlive the
    drill). */
export function cancelCue(): void {
  cancelActiveCue?.();
}

/**
 * Range diagnostic: one pass through every feedback channel — each motif in
 * sequence, a phone haptic, and a wrist buzz — so "I hear nothing" separates
 * into audio stack vs event wiring vs motor hardware in seconds.
 */
export function testFeedback(wrist: WristService): void {
  void preloadFeedback()
    .then(() => {
      SOUND_NAMES.forEach((name, i) => {
        setTimeout(() => playSound(name), i * 600);
      });
      impact(Haptics.ImpactFeedbackStyle.Medium);
      wrist.vibrate(400);
    })
    .catch(warn);
}
